<div class="admin-head"><div><span class="eyebrow">ANÁLISIS</span><h2 class="section">Centro de análisis y reportería</h2><p>Consulta ventas y pedidos con filtros combinables para análisis operativo.</p></div></div>
<form class="filter-strip analyst-filters" method="get"><input type="hidden" name="r" value="reports"><input class="form-control" name="q" maxlength="120" placeholder="Pedido, cliente o correo" value="<?=e($_GET['q']??'')?>"><input class="form-control" type="date" name="from" value="<?=e($_GET['from']??'')?>"><input class="form-control" type="date" name="to" value="<?=e($_GET['to']??'')?>"><select class="form-select searchable-select" name="status"><option value="">Todos los estados</option><?php foreach(['PEDIDO','PREPARACION','LISTO','EN_CAMINO','ENTREGADO','CANCELADO'] as $x):?><option value="<?=$x?>" <?=($_GET['status']??'')===$x?'selected':''?>><?=str_replace('_',' ',$x)?></option><?php endforeach;?></select><select class="form-select searchable-select" name="payment"><option value="">Cualquier pago</option><option value="PAGADO" <?=($_GET['payment']??'')==='PAGADO'?'selected':''?>>Pagado</option><option value="PENDIENTE" <?=($_GET['payment']??'')==='PENDIENTE'?'selected':''?>>Pendiente</option></select><select class="form-select searchable-select" name="shipping"><option value="">Cualquier entrega</option><option value="DOMICILIO" <?=($_GET['shipping']??'')==='DOMICILIO'?'selected':''?>>Domicilio</option><option value="RETIRO" <?=($_GET['shipping']??'')==='RETIRO'?'selected':''?>>Retiro</option></select><button class="btn blue">Analizar</button><a class="btn soft" href="/?r=reports">Limpiar</a></form>
